        if (m_dependentList.contains(node)) {
            for (auto neighbor : m_dependentList.at(node)) {
                if (auto locked_neighbor = neighbor.lock()) {
                    if (dfs(locked_neighbor, visited, recursionStack))
                        return true;
                }
            }
        }

        recursionStack.erase(node);
        return false;
