    void addObserver(const NodePtr &source, const NodePtr &target) {
        REACTION_REGISTER_THREAD();
        ConditionalUniqueLock<ConditionalSharedMutex> lock(m_graphMutex);

        if (source == target) {
            REACTION_THROW_SELF_OBSERVATION(getNameInternal(source));
        }

