REACTION_DEFINE_BINARY_OPERATOR(*, MulOp);
REACTION_DEFINE_BINARY_OPERATOR(-, SubOp);
REACTION_DEFINE_BINARY_OPERATOR(/, DivOp);

// === Comparison Operators ===

