REACTION_DEFINE_BINARY_OPERATOR(>, GtOp);
REACTION_DEFINE_BINARY_OPERATOR(<=, LeOp);
REACTION_DEFINE_BINARY_OPERATOR(>=, GeOp);

// === Logical Operators ===

