    React(React &&other) noexcept : m_weakPtr(std::move(other.m_weakPtr)) {
        other.m_weakPtr.reset();
    }

    /// @brief Copy assignment with reference count handling.
    React &operator=(const React &other) noexcept {
        if (this != &other) {
            safeReleaseRef();
            m_weakPtr = other.m_weakPtr;
            safeAddRef();
        }
        return *this;
