#include "test_unique_id_sequence.h"

namespace test_reaction {

UniqueIdSequence test_unique_id_sequence() {
    // Step 1: Create three UniqueID instances
    reaction::UniqueID id1;
    reaction::UniqueID id2;
    reaction::UniqueID id3;

    // Step 2: Get values from each instance
    uint64_t firstValue = id1.value();
    uint64_t secondValue = id2.value();
    uint64_t thirdValue = id3.value();

    // Step 3: Check if the sequence is strictly increasing
    bool strictlyIncreasing = (firstValue < secondValue) && 
                              (secondValue < thirdValue);

    // Step 4: Return unique ID sequence
    return UniqueIdSequence{
        firstValue,
        secondValue,
        thirdValue,
        strictlyIncreasing
    };
}

}  // namespace test_reaction
