#define REACTION_DEFINE_COMPOUND_ASSIGN_OP(OpName, symbol)      \
    struct OpName {                                             \
        template <typename T, typename U>                       \
        constexpr void operator()(T &lhs, const U &rhs) const { \
            lhs symbol rhs;                                     \
        }                                                       \
    };

// Generate all compound assignment operators using macro
