    [[nodiscard]] Type getValue() const {
        ConditionalSharedLock<ConditionalSharedMutex> lock(m_resourceMutex);
        if (!is_initialized) {
            REACTION_THROW_RESOURCE_NOT_INITIALIZED("SBOResource");
