                        if (changed) {
                            *storage.heap_ptr = std::move(newValue);
                        }
                    }
                }
            } else {
                // Non-comparable types: always assume changed
                // Fast path for always_sbo types - eliminate runtime branch
                if constexpr (always_sbo) {
