                    Type* ptr = reinterpret_cast<Type*>(const_cast<char*>(storage.buffer));
                    changed = operation(*ptr);
                } else {
                    changed = operation(*storage.heap_ptr);
                }

                if (alwaysChanged) {
                    changed = true;
